'use strict';
let csrf='',site=null,version=null,inbox=[],cursor=null,busy=false;
const $=selector=>document.querySelector(selector);
const status=text=>{$('#global-status').textContent=text;};
function node(tag,text,className){const e=document.createElement(tag);if(text)e.textContent=text;if(className)e.className=className;return e;}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.method&&options.method!=='GET'?{'X-CSRF-Token':csrf}:{}),...options.headers},cache:'no-store'});const data=await response.json();if(!response.ok){if(response.status===401)loggedOut();throw new Error(data.error||'Unable to complete the request.');}return data;}
function loggedOut(){csrf='';$('#workspace').hidden=true;$('#login-panel').hidden=false;$('#logout').hidden=true;}
async function signedIn(session){csrf=session.csrf;$('#workspace').hidden=false;$('#login-panel').hidden=true;$('#logout').hidden=false;$('#account').textContent=`Signed in as ${session.user}`;const results=await Promise.allSettled([loadContent(),loadInbox(),loadAnalytics()]);const failures=results.filter(r=>r.status==='rejected');status(failures.map(r=>r.reason.message).join(' '));}
async function work(action){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await action();}catch(e){status(e.message);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
$('#login-form').addEventListener('submit',event=>{event.preventDefault();work(async()=>{const data=Object.fromEntries(new FormData(event.target));await signedIn(await api('/api/session',{method:'POST',body:JSON.stringify(data)}));event.target.reset();});});
$('#logout').addEventListener('click',()=>work(async()=>{await api('/api/session',{method:'DELETE'});loggedOut();site=null;inbox=[];$('#inbox-list').replaceChildren();status('Signed out.');}));
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-pressed',String(b===button));$(`#panel-${b.dataset.tab}`).hidden=b!==button;});status('');}));
async function loadContent(){const data=await api('/api/content');site=data.content;version=data.version;$('#announcement').value=site.announcement;$('#announcement-my').value=site.announcementMy||'';renderNews();renderPhotos();updateOverview();}
function field(parent,labelText,value,key,item,options={}){const label=node('label',labelText);const input=node(options.multiline?'textarea':'input');input.value=value||'';input.maxLength=options.max||200;input.required=!!options.required;if(options.date)input.type='date';input.addEventListener('input',()=>{item[key]=input.value;});label.append(input);parent.append(label);return input;}
function checkbox(parent,labelText,item,key){const label=node('label',null,'check'),input=node('input');input.type='checkbox';input.checked=item[key];input.addEventListener('change',()=>{item[key]=input.checked;});label.append(input,document.createTextNode(labelText));parent.append(label);}
function renderNews(){$('#news-editor').replaceChildren();site.news.forEach(item=>{const card=node('article',null,'card'),grid=node('div',null,'two-columns');field(grid,'Title — English',item.title,'title',item,{max:160,required:true});field(grid,'Title — Myanmar',item.titleMy,'titleMy',item,{max:160});field(grid,'Date',item.date,'date',item,{max:10,date:true,required:true});checkbox(grid,'Publish on the website',item,'published');field(grid,'Story — English',item.body,'body',item,{max:3000,multiline:true,required:true}).parentElement.classList.add('full');field(grid,'Story — Myanmar',item.bodyMy,'bodyMy',item,{max:3000,multiline:true}).parentElement.classList.add('full');const remove=node('button','Remove news');remove.type='button';remove.addEventListener('click',()=>{site.news=site.news.filter(n=>n.id!==item.id);renderNews();status('News removed from the editor. Save changes to apply.');});card.append(grid,remove);$('#news-editor').append(card);});}
$('#add-news').addEventListener('click',()=>{if(site.news.length>=40)return status('Maximum 40 news items.');site.news.unshift({id:crypto.randomUUID(),title:'',titleMy:'',body:'',bodyMy:'',date:new Date().toISOString().slice(0,10),published:false});renderNews();});
async function saveSite(){site.announcement=$('#announcement').value;site.announcementMy=$('#announcement-my').value;const result=await api('/api/content',{method:'PUT',body:JSON.stringify({content:site,version})});site=result.content;version=result.version;updateOverview();}
$('#content-form').addEventListener('submit',event=>{event.preventDefault();work(async()=>{await saveSite();status('Changes saved. Published content is now available on the website.');});});
const categories={campus:'Campus',learning:'Learning','student-life':'Student life',community:'Community',information:'Information'};
function renderPhotos(){$('#photos-editor').replaceChildren();site.photos.forEach(item=>{const card=node('article',null,'card photo-editor'),image=node('img');image.src=`/api/media?id=${item.id}`;image.alt=item.caption;const content=node('div'),grid=node('div',null,'two-columns');field(grid,'Caption — English',item.caption,'caption',item,{required:true});field(grid,'Caption — Myanmar',item.captionMy,'captionMy',item);const label=node('label','Category'),select=node('select');Object.entries(categories).forEach(([key,text])=>{const option=node('option',text);option.value=key;select.append(option);});select.value=item.category;select.addEventListener('change',()=>{item.category=select.value;});label.append(select);grid.append(label);checkbox(grid,'Published',item,'published');const actions=node('div',null,'editor-actions'),save=node('button','Save photo changes'),hide=node('button','Remove from website');save.addEventListener('click',()=>work(async()=>{if(!item.caption.trim())throw new Error('English caption is required.');await saveSite();status('Photo changes saved.');}));hide.addEventListener('click',()=>work(async()=>{const before=site.photos;site.photos=site.photos.filter(p=>p.id!==item.id);try{await saveSite();renderPhotos();status('Photo removed from the website. Stored image retained.');}catch(e){site.photos=before;throw e;}}));actions.append(save,hide);content.append(grid,actions);card.append(image,content);$('#photos-editor').append(card);});}
$('#photo-form').addEventListener('submit',event=>{event.preventDefault();work(async()=>{if(site.photos.length>=100)throw new Error('Maximum 100 uploaded gallery photos.');const form=event.target,file=form.elements.photo.files[0];if(!file||file.size>2500000)throw new Error('Choose a photo under 2.5 MB.');status('Uploading and preparing photo…');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const uploaded=await api('/api/media',{method:'POST',body:JSON.stringify({image})});site.photos.unshift({id:uploaded.id,caption:form.elements.caption.value,captionMy:form.elements.captionMy.value,category:form.elements.category.value,published:form.elements.published.checked});await saveSite();form.reset();renderPhotos();status('Photo uploaded and saved.');});});
async function loadInbox(more=false){const data=await api(`/api/inbox${more&&cursor?`?cursor=${encodeURIComponent(cursor)}`:''}`);inbox=more?[...inbox,...data.items]:data.items;cursor=data.cursor;$('#load-more').hidden=!cursor;renderInbox();const setup=await api('/api/health');$('#mail-status').textContent=setup.emailConfigured?'Enquiries are saved here. Email notifications are configured; each request shows its delivery status.':'Enquiries are saved here. Email notifications are not configured yet; review new messages in this dashboard.';}
$('#refresh-inbox').addEventListener('click',()=>work(async()=>{await loadInbox();status('Inbox refreshed.');}));$('#load-more').addEventListener('click',()=>work(()=>loadInbox(true)));$('#status-filter').addEventListener('change',renderInbox);
function renderInbox(){updateOverview();const filter=$('#status-filter').value;const items=inbox.filter(x=>filter==='all'||(filter==='visits'?x.kind==='Book a school visit':x.status===filter));$('#inbox-count').textContent=`${items.length} shown · ${inbox.length} loaded`;$('#inbox-list').replaceChildren();if(!items.length)$('#inbox-list').append(node('div','No requests here yet.', 'card'));items.forEach(item=>{const card=node('article',null,'card'),heading=node('div',null,'request-heading');heading.append(node('h3',item.name),node('span',item.kind,'badge'));const info=node('div',null,'request-info'),email=node('a',item.email);email.href=`mailto:${item.email}`;info.append(email,node('span',item.phone||'No phone supplied'),node('span',new Date(item.created).toLocaleString('en-GB',{timeZone:'Asia/Yangon'})));card.append(heading,info);if(item.date)card.append(node('p',`Preferred visit: ${item.date}`));card.append(node('div',item.message,'message'),node('p',`Email notification: ${item.emailStatus} · Reference: ${item.id}`,'muted'));const notes=node('label','Internal team notes'),textarea=node('textarea');textarea.value=item.notes;textarea.maxLength=2000;notes.append(textarea);card.append(notes);const actions=node('div',null,'request-actions'),label=node('label','Status'),select=node('select');['new','in-progress','confirmed','closed'].forEach(value=>{const option=node('option',value.replace('-',' '));option.value=value;select.append(option);});select.value=item.status;label.append(select);const save=node('button','Save status & notes');save.addEventListener('click',()=>work(async()=>{const result=await api('/api/inbox',{method:'PATCH',body:JSON.stringify({id:item.id,createdKey:item.createdKey,version:item.version,status:select.value,notes:textarea.value})});inbox=inbox.map(x=>x.id===item.id?result.item:x);renderInbox();status('Request updated. Status changes do not send an email; contact the family to confirm.');}));const reply=node('a','Reply by email ↗');reply.href=`mailto:${item.email}?subject=${encodeURIComponent('Re: Guru school enquiry')}`;actions.append(label,save,reply);card.append(actions);$('#inbox-list').append(card);});}
api('/api/session').then(signedIn).catch(()=>loggedOut());

let analytics=null,trafficPeriod='daily',analyticsRequest=0;
const fmt=value=>new Intl.NumberFormat('en').format(value);
const monthNames=Array.from({length:12},(_,i)=>new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,i,1))));
const initialDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Yangon',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const initialYear=node('option',initialDate.slice(0,4));initialYear.value=initialDate.slice(0,4);$('#traffic-year').append(initialYear);
monthNames.forEach((name,index)=>{const option=node('option',name);option.value=String(index+1).padStart(2,'0');$('#traffic-month').append(option);});$('#traffic-month').value=initialDate.slice(5,7);
function updateOverview(){if(!$('#metric-enquiries'))return;$('#metric-enquiries').textContent=fmt(inbox.filter(x=>x.status==='new').length);$('#metric-visits').textContent=fmt(inbox.filter(x=>x.kind==='Book a school visit'&&!['confirmed','closed'].includes(x.status)).length);$('#metric-news').textContent=fmt(site?.news.filter(x=>x.published).length||0);$('#metric-photos').textContent=fmt(site?.photos.filter(x=>x.published).length||0);}
async function loadAnalytics(){const request=++analyticsRequest;$('#analytics-updated').textContent='Updating visitor activity…';try{const result=await api(`/api/analytics?year=${$('#traffic-year').value}&month=${$('#traffic-month').value}`);if(request!==analyticsRequest)return;analytics=result;const selectedYear=result.selectedYear;$('#traffic-year').replaceChildren();[...new Set([...result.availableYears,selectedYear])].sort().reverse().forEach(year=>{const option=node('option',year);option.value=year;$('#traffic-year').append(option);});$('#traffic-year').value=selectedYear;['today','month','year'].forEach(key=>{$(`#metric-${key}`).textContent=fmt(result[key].visitors);$(`#metric-${key}-visits`).textContent=`${fmt(result[key].visits)} visits · unique browsers`});$('#analytics-updated').textContent=`Updated ${new Date(result.updated).toLocaleTimeString('en-GB',{timeZone:'Asia/Yangon',hour:'2-digit',minute:'2-digit'})} · Myanmar time`;$('#tracking-start').textContent=result.firstTrackedDate?`First recorded visit: ${result.firstTrackedDate}. Earlier traffic is unavailable.`:'Tracking has started. Your first visitor will appear here; earlier traffic is unavailable.';renderTraffic();}catch(e){if(request!==analyticsRequest)return;$('#analytics-updated').textContent='Traffic could not be loaded. Use Refresh to try again.';throw e;}}
function chartRows(){return analytics?.[trafficPeriod]||[];}
function renderTraffic(){if(!analytics)return;$('#traffic-month-label').hidden=trafficPeriod!=='daily';$('#traffic-year-label').hidden=trafficPeriod==='yearly';document.querySelectorAll('[data-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.period===trafficPeriod)));const rows=chartRows(),measure=$('#traffic-measure').value,measureLabel=measure==='visitors'?'Unique visitors':'Visits',year=analytics.selectedYear,month=monthNames[Number(analytics.selectedMonth)-1];$('#traffic-range').textContent=trafficPeriod==='daily'?`${month} ${year} · day by day`:trafficPeriod==='monthly'?`${year} · month by month`:'All recorded years';$('#traffic-table').replaceChildren();rows.forEach(row=>{const tr=node('tr');tr.append(node('th',row.key),node('td',fmt(row.visitors)),node('td',fmt(row.visits)));tr.firstElementChild.scope='row';$('#traffic-table').append(tr);});const total=rows.reduce((sum,row)=>sum+row[measure],0);$('#traffic-empty').hidden=total!==0;$('#traffic-total').textContent=measure==='visitors'?`${fmt(total)} visitor-period counts · a returning browser can appear in multiple periods`:`${fmt(total)} visits in this view`;const container=$('#traffic-chart');container.replaceChildren();const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 300');svg.setAttribute('role','img');svg.setAttribute('aria-label',`${measureLabel}, ${trafficPeriod} traffic. ${rows.map(r=>`${r.key}: ${r[measure]}`).join('; ')}`);container.setAttribute('aria-label',`${measureLabel} by ${trafficPeriod} period`);const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([key,value])=>e.setAttribute(key,String(value)));if(text!==undefined)e.textContent=text;svg.append(e);return e;};const max=Math.max(1,...rows.map(r=>r[measure])),step=Math.max(1,Math.ceil(max/4)),top=step*4;for(let i=0;i<=4;i++){const y=250-i*52;add('line',{x1:55,x2:985,y1:y,y2:y,class:'chart-grid'});add('text',{x:44,y:y+4,'text-anchor':'end',class:'chart-tick'},fmt(step*i));}add('text',{x:55,y:20,class:'chart-tick'},measureLabel);const spacing=930/Math.max(1,rows.length),width=Math.min(48,spacing*.62);rows.forEach((row,index)=>{const height=row[measure]/top*208,x=55+index*spacing+spacing/2;const bar=add('rect',{x:x-width/2,y:250-height,width,height:Math.max(height,row[measure]?3:0),rx:4,class:'chart-bar',tabindex:0});const title=document.createElementNS(ns,'title');title.textContent=`${row.key}: ${fmt(row.visitors)} unique visitors, ${fmt(row.visits)} visits`;bar.append(title);if(rows.length<=16||index%2===0)add('text',{x,y:276,'text-anchor':'middle',class:'chart-tick'},row.label);if(row[measure]&&rows.length<=16)add('text',{x,y:240-height,'text-anchor':'middle',class:'chart-label'},fmt(row[measure]));});container.append(svg);}
document.querySelectorAll('[data-period]').forEach(button=>button.addEventListener('click',()=>{trafficPeriod=button.dataset.period;renderTraffic();}));$('#traffic-measure').addEventListener('change',renderTraffic);['#traffic-year','#traffic-month'].forEach(selector=>$(selector).addEventListener('change',()=>work(loadAnalytics)));$('#refresh-analytics').addEventListener('click',()=>work(loadAnalytics));
$('#export-traffic').addEventListener('click',()=>{if(!analytics)return status('Load visitor activity first.');const rows=chartRows();const csv=['Period,Unique browser visitors,Visits',...rows.map(row=>`${row.key},${row.visitors},${row.visits}`)].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=node('a');link.href=url;link.download=`guru-traffic-${trafficPeriod}-${analytics.selectedYear}-${analytics.selectedMonth}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
